/**
 * Image-path QR decoding: does a picture of a QR become the right binary matrix?
 *
 * Why this test exists: the phone can now decode a QR out of a picked image, and that path rests on
 * two steps the camera path never needed — turning ARGB pixels into a luminance plane, and
 * binarising a photographic image rather than a raw camera frame. A mistake there is invisible:
 * the scanner simply never finds a code, which looks identical to "the user picked a bad picture".
 *
 * What it checks: a symbol generated by this package's own encoder is rendered into an image the
 * way a screenshot or photo would arrive (scaled, quiet zone, optionally rotated), run through the
 * same luminance extraction and both binarizers the app uses, and then sampled at the module centres
 * and compared with the original matrix. A mismatch means the app would not have decoded it.
 *
 * No network, no browser, no image library: the "image" is an int[] exactly like the one
 * Bitmap.getPixels() returns, which is what makes this a faithful check of the app's input.
 *
 * Run: node test/image-decode-test.cjs
 */

'use strict';

const assert = require('node:assert');

let failures = 0;
let checks = 0;

function check(name, condition, detail) {
  checks++;
  if (condition) {
    console.log('  ok   ' + name);
  } else {
    failures++;
    console.log('  FAIL ' + name + (detail ? '  → ' + detail : ''));
  }
}

// ---- the two colours a QR screenshot is made of ------------------------------

const DARK = 0xff000000; // opaque black, as getPixels() reports it
const LIGHT = 0xffffffff; // opaque white

/**
 * Render a QR matrix into an ARGB pixel array.
 *
 * @param {boolean[][]} matrix - modules, true = dark
 * @param {object} options - scale (pixels per module), quiet (modules of margin), rotate (degrees)
 */
function renderImage(matrix, options = {}) {
  const scale = options.scale ?? 8;
  const quiet = options.quiet ?? 4;
  const rotate = options.rotate ?? 0;

  const modules = matrix.length;
  const side = (modules + quiet * 2) * scale;
  const pixels = new Array(side * side).fill(LIGHT);

  for (let my = 0; my < modules; my++) {
    for (let mx = 0; mx < modules; mx++) {
      if (!matrix[my][mx]) continue;
      const px0 = (mx + quiet) * scale;
      const py0 = (my + quiet) * scale;
      for (let dy = 0; dy < scale; dy++) {
        const row = (py0 + dy) * side;
        for (let dx = 0; dx < scale; dx++) {
          const idx = toRotated(px0 + dx, py0 + dy, side, rotate);
          pixels[idx] = DARK;
        }
      }
    }
  }
  return { pixels, width: side, height: side, scale, quiet };
}

/** Map an (x, y) in the un-rotated image onto its place in the rotated image. */
function toRotated(x, y, side, rotate) {
  if (rotate === 90) return x * side + (side - 1 - y);
  if (rotate === 180) return (side - 1 - y) * side + (side - 1 - x);
  if (rotate === 270) return (side - 1 - x) * side + y;
  return y * side + x;
}

/** Turn a rotated image back so a module centre can be located in it. */
function fromRotated(rx, ry, side, rotate) {
  if (rotate === 90) return { x: ry, y: side - 1 - rx };
  if (rotate === 180) return { x: side - 1 - rx, y: side - 1 - ry };
  if (rotate === 270) return { x: side - 1 - ry, y: rx };
  return { x: rx, y: ry };
}

// ---- the app's luminance extraction, ported exactly --------------------------
//
// ZXing 3.5.3's RGBLuminanceSource has a single `int[]` constructor and reads the channels as
//   r = (pixel >> 16) & 0xff, g = (pixel >> 8) & 0xff, b = pixel & 0xff
// which is exactly what Android's ARGB_8888 pixels give it, because the alpha byte sits above the
// red one. Ported here rather than assumed, so a wrong channel order would fail this test.

function toLuminance(pixels) {
  const out = Buffer.alloc(pixels.length);
  for (let i = 0; i < pixels.length; i++) {
    const p = pixels[i];
    const r = (p >> 16) & 0xff;
    const g = (p >> 8) & 0xff;
    const b = p & 0xff;
    out[i] = (r + 2 * g + b) / 4 | 0;
  }
  return out;
}

// ---- the app's two binarizers, ported ---------------------------------------

/**
 * ZXing's HybridBinarizer: per-8x8-block local mean over a 5x5 block neighbourhood, with a global
 * histogram fallback for blocks whose contrast is too low to threshold locally.
 *
 * The port keeps the structure that matters for this test: local means, the low-contrast fallback,
 * and the black-point estimate. Where exact rounding differs from the Java by a single level, the
 * module-centre sampling below still decides correctly — that is the property being verified.
 */
function hybridBinarize(luma, width, height) {
  const BLOCK = 8;
  const bw = Math.ceil(width / BLOCK);
  const bh = Math.ceil(height / BLOCK);
  const blackPoints = new Int32Array(bw * bh);

  for (let by = 0; by < bh; by++) {
    for (let bx = 0; bx < bw; bx++) {
      let sum = 0;
      let min = 255;
      let max = 0;
      let count = 0;
      for (let y = 0; y < BLOCK; y++) {
        const py = by * BLOCK + y;
        if (py >= height) break;
        for (let x = 0; x < BLOCK; x++) {
          const px = bx * BLOCK + x;
          if (px >= width) break;
          const v = luma[py * width + px];
          sum += v;
          if (v < min) min = v;
          if (v > max) max = v;
          count++;
        }
      }
      let average = count ? sum / count : 0;
      if (max - min <= 24) {
        // Low contrast: assume the block sits next to a large dark or light area and lean towards
        // the global histogram, as ZXing does.
        average = min / 2;
        if (by > 0 && bx > 0) {
          const neighbour = (blackPoints[(by - 1) * bw + bx]
            + 2 * blackPoints[by * bw + bx - 1]
            + blackPoints[(by - 1) * bw + bx - 1]) / 4;
          if (min < neighbour) average = neighbour;
        }
      }
      blackPoints[by * bw + bx] = average | 0;
    }
  }

  const out = Buffer.alloc(width * height);
  for (let by = 0; by < bh; by++) {
    for (let bx = 0; bx < bw; bx++) {
      let sum = 0;
      let count = 0;
      for (let dy = -2; dy <= 2; dy++) {
        const ny = Math.min(bh - 1, Math.max(0, by + dy));
        for (let dx = -2; dx <= 2; dx++) {
          const nx = Math.min(bw - 1, Math.max(0, bx + dx));
          sum += blackPoints[ny * bw + nx];
          count++;
        }
      }
      const threshold = sum / count;
      for (let y = 0; y < BLOCK; y++) {
        const py = by * BLOCK + y;
        if (py >= height) break;
        for (let x = 0; x < BLOCK; x++) {
          const px = bx * BLOCK + x;
          if (px >= width) break;
          out[py * width + px] = luma[py * width + px] <= threshold ? 0 : 255;
        }
      }
    }
  }
  return out;
}

/** ZXing's GlobalHistogramBinarizer: one threshold from the 32-bucket luminance histogram. */
function globalBinarize(luma, width, height) {
  const buckets = new Int32Array(32);
  const stride = Math.max(1, Math.floor(height / 5));
  for (let y = stride - 1; y < height; y += stride) {
    for (let x = 0; x < width; x++) {
      buckets[luma[y * width + x] >> 3]++;
    }
  }
  let firstPeak = 0;
  let firstPeakSize = 0;
  let maxBucketCount = 0;
  for (let i = 0; i < 32; i++) {
    if (buckets[i] > firstPeakSize) {
      firstPeak = i;
      firstPeakSize = buckets[i];
    }
    if (buckets[i] > maxBucketCount) maxBucketCount = buckets[i];
  }
  let secondPeak = 0;
  let secondPeakScore = 0;
  for (let i = 0; i < 32; i++) {
    const distance = Math.abs(i - firstPeak);
    const score = buckets[i] * distance * distance;
    if (score > secondPeakScore) {
      secondPeak = i;
      secondPeakScore = score;
    }
  }
  if (firstPeak > secondPeak) {
    const t = firstPeak;
    firstPeak = secondPeak;
    secondPeak = t;
  }
  if (secondPeak - firstPeak <= 32 / 16) {
    // No usable contrast: everything is one shade, so nothing is "black".
    return Buffer.alloc(width * height, 255);
  }
  let bestValley = secondPeak - 1;
  let bestValleyScore = -1;
  for (let i = secondPeak - 1; i > firstPeak; i--) {
    const fromFirst = i - firstPeak;
    const score = fromFirst * fromFirst * (secondPeak - i) * (maxBucketCount - buckets[i]);
    if (score > bestValleyScore) {
      bestValley = i;
      bestValleyScore = score;
    }
  }
  const threshold = bestValley << 3;
  const out = Buffer.alloc(width * height);
  for (let i = 0; i < luma.length; i++) out[i] = luma[i] <= threshold ? 0 : 255;
  return out;
}

// ---- sampling and comparison ------------------------------------------------

/**
 * Read back the module at (mx, my) from a binarised image by sampling its centre.
 *
 * Sampling the centre rather than counting an average is deliberate: it is what a decoder does, and
 * it is what makes this test reject a binarisation that blurs module edges together.
 */
function sampleModule(binary, width, side, mx, my, scale, quiet, rotate) {
  const cx = (mx + quiet) * scale + (scale >> 1);
  const cy = (my + quiet) * scale + (scale >> 1);
  const p = fromRotated(cx, cy, side, rotate);
  return binary[p.y * width + p.x] === 0;
}

function compare(matrix, binary, image, rotate) {
  let wrong = 0;
  let firstWrong = '';
  for (let my = 0; my < matrix.length; my++) {
    for (let mx = 0; mx < matrix[my].length; mx++) {
      const got = sampleModule(binary, image.width, image.width, mx, my, image.scale, image.quiet, rotate);
      if (got !== matrix[my][mx]) {
        wrong++;
        if (!firstWrong) firstWrong = 'module(' + mx + ',' + my + ') expected '
          + (matrix[my][mx] ? 'dark' : 'light');
      }
    }
  }
  return { wrong, firstWrong, total: matrix.length * matrix.length };
}

/**
 * The app's rotation ladder: try the image as given, then 90, 180, 270, and accept the first
 * orientation whose sampled modules all match. This mirrors `decodeBitmap`'s loop, which accepts the
 * first orientation that decodes.
 */
function decodeLikeApp(matrix, pixels, width) {
  for (const rotate of [0, 90, 180, 270]) {
    const luma = toLuminance(pixels);
    for (const [name, binarize] of [['hybrid', hybridBinarize], ['global', globalBinarize]]) {
      const binary = binarize(luma, width, width);
      const result = compare(matrix, binary, { width, scale: 8, quiet: 4 }, rotate);
      if (result.wrong === 0) return { rotate, binarizer: name };
    }
  }
  return null;
}

// ---- the cases ---------------------------------------------------------------

async function main() {
  const { encodeMatrix } = await import('../lib/qr.js');
  const payload = 'http://192.168.31.56:19387/m/pair?t=On8eDqV6JaRereufImjjC_L7Nfs_aymv&secret=7lk2GMhIpSLOHCGzyaxb0fQzx2ub4i7T';
  // encodeMatrix returns numbers, and its truthy value is the dark module — that is the convention
  // toSvg relies on (`if (!modules[r][c]) continue;`). Normalised to booleans here so the rest of
  // the test compares like with like; an earlier revision compared booleans against numbers and so
  // reported every single module as wrong.
  const raw = encodeMatrix(payload);
  const matrix = raw.map((row) => Array.from(row, (v) => Boolean(v)));
  const modules = matrix.length;
  console.log('测试符号: ' + modules + 'x' + modules + ' 模块, 载荷 ' + payload.length + ' 字符');
  console.log();

  // The finder patterns are a known shape, so they are what confirms the convention above rather
  // than the other way round.
  const finderOk = (ox, oy) => {
    for (let y = 0; y < 7; y++) {
      for (let x = 0; x < 7; x++) {
        const edge = x === 0 || x === 6 || y === 0 || y === 6;
        const core = x >= 2 && x <= 4 && y >= 2 && y <= 4;
        if (matrix[oy + y][ox + x] !== (edge || core)) return false;
      }
    }
    return true;
  };
  check('定位图案符合 7x7 规范（确认 真=黑 的约定）',
    finderOk(0, 0) && finderOk(modules - 7, 0) && finderOk(0, modules - 7));
  console.log();

  // The orientation ladder must recover an image that arrived rotated.
  for (const rotate of [0, 90, 180, 270]) {
    const image = renderImage(matrix, { rotate });
    const found = decodeLikeApp(matrix, image.pixels, image.width);
    check('旋转 ' + String(rotate).padStart(3) + '° 的图片能解码',
      found !== null,
      found ? null : '四种旋转 × 两种二值化都没能还原矩阵');
    if (found) {
      console.log('       → 用 ' + found.rotate + '° + ' + found.binarizer + ' 解得');
    }
  }

  // Scale matters: a screenshot may be small, a photo large. The QR must survive both.
  for (const scale of [3, 5, 16]) {
    const image = renderImage(matrix, { scale });
    const luma = toLuminance(image.pixels);
    const hybrid = hybridBinarize(luma, image.width, image.width);
    const result = compare(matrix, hybrid, { width: image.width, scale, quiet: 4 }, 0);
    check('缩放 ' + scale + ' px/模块 时模块取样全对', result.wrong === 0,
      result.wrong ? result.wrong + '/' + result.total + ' 个模块不符，首个 ' + result.firstWrong : null);
  }

  // Contrast: a real photo is not pure black on pure white, and a low-contrast image is exactly
  // where a luminance or binarisation mistake shows up.
  for (const [label, dark, light] of [['低对比度', 0xff707070, 0xffd0d0d0], ['偏色', 0xff203040, 0xfff0e8d8]]) {
    const image = renderImage(matrix, { scale: 8, dark, light });
    const found = decodeLikeApp(matrix, image.pixels, image.width);
    check(label + '图片仍能解码', found !== null);
  }

  // A quiet zone is required by the spec and easy to lose when cropping a screenshot.
  for (const quiet of [1, 4]) {
    const image = renderImage(matrix, { quiet });
    const luma = toLuminance(image.pixels);
    const hybrid = hybridBinarize(luma, image.width, image.width);
    const result = compare(matrix, hybrid, { width: image.width, scale: 8, quiet }, 0);
    check('白边 ' + quiet + ' 个模块时取样全对', result.wrong === 0,
      result.wrong ? result.wrong + ' 个模块不符' : null);
  }

  console.log();
  if (failures) {
    console.log(failures + ' / ' + checks + ' 项失败');
    process.exit(1);
  }
  console.log('ALL IMAGE DECODE CHECKS PASSED (' + checks + ' 项)');
}

main().catch((error) => {
  console.error('测试自身出错: ' + (error && error.stack || error));
  process.exit(1);
});
